@NoArgsConstructor
@AllArgsConstructor
@Builder
@Table(name = "users")
public class User extends BaseTimeEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "grade_id")
    private UserGrade grade; // 회원 등급

    @Builder.Default
    @Column(nullable = false, columnDefinition = "BIT(1) DEFAULT 1")
    private boolean isActive = true; // 계정 활성화

    // **편의 메서드 - 값 업데이트**
    public void addOAuthConnection(String provider, String providerId) {
        // 이미 해당 프로바이더에 대한 연결이 있는지 확인
        boolean connectionExists = this.oauthConnections.stream()
                .anyMatch(conn -> conn.getProvider().equals(provider));

        if (!connectionExists) {
            OAuthConnection connection = OAuthConnection.builder()
                    .provider(provider)
                    .providerId(providerId)
                    .connectedAt(LocalDateTime.now())
                    .build();

            connection.setUser(this);
            this.oauthConnections.add(connection);
        }
    }

    public void addGrade(UserGrade grade) {
        this.grade = grade;
    }

    public void addActive(boolean active) {
        isActive = active;
    }

    public void setVerified(boolean verified) {
        this.isVerified = verified;
    }
