import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.List;
import java.util.Optional;

public interface InterestRepository extends JpaRepository<Interest, Long> {
    boolean existsByUserAndProductColor(User user, ProductColor productColor);

    Optional<Interest> findByUserAndProductColor(User user, ProductColor productColor);

    List<Interest> findAllByUserId(Long userId);

    /**
     * 상품 색상을 관심 등록한 활성 회원 ID 목록 (제외 회원 제외)
     */
    @Query("select i.user.id from Interest i " +
            "where i.productColor.id = :productColorId " +
            "and i.user.isActive = true " +
            "and i.user.id <> :excludedUserId")
    List<Long> findActiveUserIdsByProductColorIdExcluding(@Param("productColorId") Long productColorId,
                                                          @Param("excludedUserId") Long excludedUserId);
}

