package com.fream.back.domain.notification.listener;

import com.fream.back.domain.notification.entity.NotificationCategory;
import com.fream.back.domain.notification.entity.NotificationType;
import com.fream.back.domain.notification.service.command.NotificationCommandService;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.entity.ProductColor;
import com.fream.back.domain.product.entity.ProductSize;
import com.fream.back.domain.product.repository.InterestRepository;
import com.fream.back.domain.sale.entity.SaleBid;
import com.fream.back.domain.sale.event.SaleBidCreatedEvent;
import lombok.RequiredArgsConstructor;
import org.springframework.context.event.EventListener;
import org.springframework.stereotype.Component;

/**
 * 새 판매 입찰이 등록되면 그 사이즈의 색상을 관심 등록한 회원에게 알린다.
 */
@Component
@RequiredArgsConstructor
public class FavoriteListingAlertListener {

    private final InterestRepository interestRepository;
    private final NotificationCommandService notificationCommandService;

    @EventListener
    public void onSaleBidCreated(SaleBidCreatedEvent event) {
        SaleBid saleBid = event.saleBid();
        ProductSize productSize = saleBid.getProductSize();
        ProductColor productColor = productSize.getProductColor();
        Product product = productColor.getProduct();

        String message = String.format("관심 상품 '%s' 사이즈 %s에 새 판매 입찰이 등록되었습니다. 판매 희망가 %,d원",
                product.getName(), productSize.getSize(), saleBid.getBidPrice());

        List<Long> userIds = interestRepository.findActiveUserIdsByProductColorIdExcluding(
                productColor.getId(), saleBid.getSeller().getId());
        for (Long userId : userIds) {
            notificationCommandService.createNotification(
                    userId,
                    NotificationCategory.SHOPPING,
                    NotificationType.FAVORITE,
                    message
            );
        }
    }
}

